const shopifyAppSlug = 'klaviyo-email-marketing';
const wpPluginSlug = 'woocommerce-payments';
return [{
  json: {
    shopifyAppSlug,
    wpPluginSlug,
    shopifyUrl: `https://apps.shopify.com/${encodeURIComponent(shopifyAppSlug)}/reviews?ratings[]=1`,
    wpRssUrl: `https://wordpress.org/support/plugin/${encodeURIComponent(wpPluginSlug)}/reviews/feed/?filter=1`,
  },
}];

const cfg = $('Configure Store Targets').first().json;
const shopifyHtml = String(($('Fetch Shopify 1-Star Reviews').first().json || {}).data ?? ($('Fetch Shopify 1-Star Reviews').first().json || {}).body ?? '');
const wpXml = String(($('Fetch WooCommerce 1-Star RSS').first().json || {}).data ?? ($('Fetch WooCommerce 1-Star RSS').first().json || {}).body ?? '');

const painRules = {
  billing_pricing: /\b(bill|billing|price|pricing|expensive|fee|charge|cost|cancel|refund|subscription)\b/i,
  bugs_breakage: /\b(broken|bug|crash|error|fail|slow|conflict|update|sync|doesn.?t work)\b/i,
  support_churn: /\b(support|no reply|ignored|worst|waste|uninstall|switch|alternative)\b/i,
};
const tagPain = (text) => Object.entries(painRules).filter(([, rx]) => rx.test(text)).map(([k]) => k);
const out = [];

// 1. Parse Shopify 1-star review blocks
const shopBlocks = shopifyHtml.split('data-review-content-id="').slice(1, 11);
for (const b of shopBlocks) {
  const reviewId = b.split('"', 1)[0];
  const txtMatch = b.match(/data-truncate-content-copy[^>]*>([\s\S]*?)<\/div>/);
  const excerpt = txtMatch ? txtMatch[1].replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim() : '';
  const dateMatch = b.match(/<div class="tw-text-body-xs tw-text-fg-tertiary">\s*([^<]+?)\s*<\/div>/);
  if (excerpt) {
    out.push({
      json: {
        platform: 'shopify-app-store',
        appOrPlugin: cfg.shopifyAppSlug,
        reviewId,
        rating: 1,
        reviewDate: dateMatch ? dateMatch[1].trim() : null,
        painCategories: tagPain(excerpt),
        excerpt: excerpt.slice(0, 260),
        sourceUrl: cfg.shopifyUrl,
      },
    });
  }
}

// 2. Parse WordPress.org / WooCommerce 1-star RSS items
for (const m of [...wpXml.matchAll(/<item>([\s\S]*?)<\/item>/g)].slice(0, 10)) {
  const block = m[1];
  const getTag = (tag) => {
    const hit = block.match(new RegExp(`<${tag}[^>]*>([\\s\\S]*?)<\\/${tag}>`, 'i'));
    return hit ? hit[1].replace(/<!\[CDATA\[|\]\]>/g, '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim() : '';
  };
  const title = getTag('title');
  const desc = getTag('description');
  out.push({
    json: {
      platform: 'wordpress-woocommerce',
      appOrPlugin: cfg.wpPluginSlug,
      reviewId: getTag('guid') || getTag('link'),
      rating: 1,
      reviewDate: getTag('pubDate'),
      painCategories: tagPain(`${title} ${desc}`),
      excerpt: `${title} — ${desc}`.slice(0, 260),
      sourceUrl: getTag('link') || cfg.wpRssUrl,
    },
  });
}

return out.length ? out : [{ json: { status: 'no_1star_reviews_parsed' } }];
